function match(s,a,b){let x=0,y=0,quarters=[];for(let q=0;q<4;q++){let qx=0,qy=0;for(let d=0;d<3;d++){let p=clamp(.37+(a.off-b.def)/110,.12,.76),p2=clamp(.37+(b.off-a.def)/110,.12,.76);if(rng(s)<p)qx+=rng(s)<.72?7:3;if(rng(s)<p2)qy+=rng(s)<.72?7:3;}x+=qx;y+=qy;quarters.push([qx,qy]);}if(x===y){if(rng(s)<.5+(a.off-b.off)/200)x+=3;else y+=3;}return {x,y,quarters};}
function play(s){if(s.phase!=='regular')return;const u=units(s),boost=s.plan==='win'?3:s.plan==='youth'?-4:0,mod=(s.morale-50)/18;for(const [ai,bi]of s.schedule[s.week]){let a=s.teams[ai],b=s.teams[bi],rate=t=>t.id===0?{off:u.off+boost+mod,def:u.def+boost+mod}:{off:t.rating+(t.mode==='Contending'?2:0),def:t.rating};let r=match(s,rate(a),rate(b));a.pf+=r.x;a.pa+=r.y;b.pf+=r.y;b.pa+=r.x;(r.x>r.y?a:b).w++;(r.x>r.y?b:a).l++;if(ai===0||bi===0){let us=ai===0?r.x:r.y,them=ai===0?r.y:r.x,opp=ai===0?b:a,win=us>them,margin=Math.abs(us-them);let growth=0;s.roster.forEach(p=>{if(p.age<=25&&p.rating<p.potential){let g=s.plan==='youth'?1.3:s.plan==='win'?.2:.6;p.rating=Math.min(p.potential,p.rating+g);growth+=g;}});let running=0,closeQuarters=0;const ourQuarters=ai===0?r.quarters:r.quarters.map(q=>[q[1],q[0]]);ourQuarters.slice(0,3).forEach(q=>{running+=q[0]-q[1];if(Math.abs(running)<=10)closeQuarters++;});let reasons=win?[['Win',-9]]:[['Loss',8],['Competitive game',margin<=7&&closeQuarters>=2?-4:0],['Heavy defeat',margin>=21?6:0],['Stronger opponent',opp.rating>u.overall+8?-2:0],['Youth development',growth>4?-2:0],['Clear team identity',us>=28||them<=13?-1:0]];if(!win&&s.week>=5&&s.teams[0].w<2)reasons.push(['Losing season pressure',3]);let rawChange=reasons.reduce((n,r)=>n+r[1],0),change=weightedHeat(s,rawChange);if(change<rawChange)reasons.push([`Tenure grace (${Math.round(scrutiny(s)*100)}% scrutiny)`,Math.round((change-rawChange)*10)/10]);s.heat=clamp(Math.round((s.heat+change)*10)/10,0,100);s.morale=clamp(s.morale+(win?6:margin<=7?-1:-5),15,100);s.fans=clamp(s.fans+(win?4:margin<=7?0:-3),10,100);s.result={us,them,opp:opp.name,win,reasons,quarters:ai===0?r.quarters:r.quarters.map(q=>[q[1],q[0]]),headline:win?'A win buys breathing room.':margin<=7?'A loss you can defend.':'Ownership wants answers.'};s.log.unshift(`Week ${s.week+1}: ${win?'W':'L'} ${us}–${them} vs ${opp.name}`);}else{let loser=r.x>r.y?b:a;loser.heat+=5;if(loser.heat>55){loser.mode='Competing';loser.rating+=.5;}}}
s.week++;s.trained=[];s.teams[0].rating=units(s).overall;if(s.week%3===0&&s.market.length){let signed=s.market.splice(Math.floor(rng(s)*s.market.length),1)[0],t=s.teams[1+Math.floor(rng(s)*15)];t.rating+=1;s.log.unshift(`${t.name} signed ${signed.name} (${signed.pos}).`);}if(s.heat>=100){s.phase='fired';return;}if(s.week===10){let rank=standings(s).findIndex(t=>t.id===0);s.phase=rank<6?'playoffs':'review';s.playoffRound=0;s.log.unshift(rank<6?'Playoff berth secured. Three wins from a title.':'Season complete. Your rebuild goes to ownership review.');}}
function train(s,i){let p=s.roster[i];if(!canManage(s)||spendable(s)<3||s.trained.length>=2||s.trained.includes(i)||p.rating>=p.potential)return false;s.cash-=3;p.rating=Math.min(p.potential,p.rating+2);s.trained.push(i);return true;}
function sign(s,id){let j=s.market.findIndex(p=>p.id===id);if(j<0||!canManage(s))return false;let p=s.market[j],i=positions.indexOf(p.pos);if(spendable(s)<p.salary)return false;s.cash-=p.salary;s.roster[i]={...p};s.market.splice(j,1);s.log.unshift(`Signed ${p.name}: $${p.salary}M per season, 2 years.`);return true;}
function trade(s,i){if(!['offseason','regular'].includes(s.phase)||s.week>=6||s.tradedThisSeason)return false;let p=s.roster[i];if(p.rating<60)return false;s.cash+=5;s.tradedThisSeason=true;if(s.phase==='offseason'&&!s.draftComplete){s.draftSlots.push(30);s.draftSlots.sort((a,b)=>a-b);}else s.extraPick=1;s.roster[i]=player(s,i,43,true);s.roster[i].name='Practice squad';let tradeHeat=weightedHeat(s,5);s.heat=clamp(Math.round((s.heat+tradeHeat)*10)/10,0,100);s.log.unshift(`Traded ${p.name} for $5M and an extra draft selection. Heat +${tradeHeat} (year ${s.season} scrutiny).`);if(s.heat>=100)s.phase='fired';return true;}
function playoffs(s){if(s.phase!=='playoffs')return;let opponents=standings(s).filter(t=>t.id!==0).slice(0,5),opp=opponents[Math.max(0,4-s.playoffRound*2)],u=units(s),r=match(s,{off:u.off+3,def:u.def+3},{off:opp.rating,def:opp.rating});s.result={us:r.x,them:r.y,opp:opp.name,win:r.x>r.y,quarters:r.quarters,reasons:[],headline:r.x>r.y?'The dream is alive.':'The postseason ends here.'};if(r.x>r.y){s.bonus+=5;s.heat=Math.max(0,s.heat-10);s.playoffRound++;if(s.playoffRound===3)s.phase='champion';}else s.phase='review';}
function review(s){if(s.phase!=='review')return;let t=s.teams[0],expect=Math.min(6,s.season+1),rawPenalty=t.w<expect?(expect-t.w)*5:-8,penalty=weightedHeat(s,rawPenalty);s.heat=clamp(Math.round((s.heat+penalty)*10)/10,0,100);s.log.unshift(`Owner review: ${t.w}/${expect} expected wins. Heat ${penalty>=0?'+':''}${penalty}${penalty<rawPenalty?` (year ${s.season} grace: ${Math.round((rawPenalty-penalty)*10)/10} heat waived)`:""}.`);if(s.heat>=100){s.phase='fired';return;}nextSeason(s);}

function moveUp(s){if(s.phase!=='draft'||s.draftTurn!==0||s.pick<3||spendable(s)<12||s.movedUp)return false;s.cash-=12;s.pick-=2;s.draftSlots[0]=s.pick;s.movedUp=true;for(let j=0;j<2;j++)s.prospects.push({...player(s,Math.floor(rng(s)*12),Math.max(60,84-s.pick),true),rank:s.pick+j});s.prospects.sort((a,b)=>a.rank-b.rank);return true;}
function draft(s,rank){if(s.phase!=='draft')return;let p=s.prospects.find(p=>p.rank===rank);if(!p||(!s.legacyDraft&&s.cash<3))return;if(!s.legacyDraft)s.cash-=3;s.roster[positions.indexOf(p.pos)]={...p};s.log.unshift(`Drafted ${p.name}, ${p.pos}, ${Math.round(p.rating)} OVR.`);s.prospects=s.prospects.filter(p=>p.rank!==rank);s.draftTurn++;if(s.draftTurn<s.draftSlots.length){s.prospects=s.prospects.filter(p=>p.rank>=s.draftSlots[s.draftTurn]);}else if(s.legacyDraft){s.legacyDraft=false;nextSeason(s,true);}else{s.draftComplete=true;s.phase='offseason';s.log.unshift('Draft complete. Finish your roster moves, then start the season.');}}
function nextSeason(s,skipDraft=false){let earnedPick=draftOrder(s).findIndex(t=>t.id===0)+1,earnedExtra=s.extraPick;let t=s.teams[0];s.history.push({season:s.season,w:t.w,l:t.l,heat:s.heat});s.budget=80+t.w*2+s.bonus+Math.floor(s.fans/10);let carry=Math.min(10,s.cash);s.roster.forEach((p,i)=>{p.age++;p.years--;if(p.years<=0){p.salary=Math.max(3,Math.round((p.rating-45)/4));p.years=1;}if(p.age>29)p.rating=Math.max(40,p.rating-2);});s.cash=s.budget-s.roster.reduce((n,p)=>n+p.salary,0)+carry;while(s.cash<(skipDraft?0:6+(earnedExtra?3:0))){let p=[...s.roster].sort((a,b)=>b.salary-a.salary)[0],i=s.roster.indexOf(p);s.cash+=p.salary-2;s.roster[i]=player(s,i,45,true);s.roster[i].salary=2;s.log.unshift(`Budget cut: ${p.name} released for a low-cost replacement.`);}s.season++;s.week=0;s.phase='offseason';s.tradedThisSeason=false;s.bonus=0;s.extraPick=0;s.movedUp=false;s.result=null;s.trained=[];s.teams.forEach(t=>{t.w=t.l=t.pf=t.pa=0;if(t.id)t.rating=clamp(t.rating+(t.mode==='Rebuilding'?3:-1)+rng(s)*2,50,90);});schedule(s);market(s);if(skipDraft)s.draftComplete=true;else prepareDraft(s,earnedPick,earnedExtra);s.log.unshift(`Season ${s.season}: $${s.budget}M funding; $${s.cash}M available after salaries and carryover.`);}
